      id: "pro01",
      num: 1,
      titulo: "O relator poderá conceder o efeito suspensivo ao recurso ou deferir, em antecipa-",
      conteudo: `ção de tutela, total ou parcialmente, a pretensão recursal, comunicando ao juiz sua
decisão.`
